/**
 * Portal configuration. `portal.config.json` is generated by the project's
 * scripts/build_portal.py from config/salesforce/portal.json; edit that file,
 * not the JSON here, so regeneration keeps your change.
 */
import raw from "./portal.config.json";

export interface FieldConfig {
	api_name: string;
	label: string;
}

export interface PortalConfig {
	title: string;
	record: {
		object: string;
		label: string;
		plural_label: string;
		title_field: string;
		stage_field: string | null;
		status_field: string | null;
		fields: FieldConfig[];
	};
	stages: string[];
	documents: null | {
		relationship: string;
		label: string;
		type_field: string;
		status_field: string;
		version_field?: string | null;
		hidden_types: string[];
	};
	status_tone: Record<string, "pass" | "wait" | "fail">;
}

export const portalConfig = raw as PortalConfig;
